import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.json.*;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String userId = req.getParameter("uid");

        // Basic input presence check
        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed list
        if (!reportType.matches("^(sales|inventory|audit|payroll)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date range validation - looks safe but sortCol is not validated
        if (!dateRange.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");

        try (Connection conn = getConnection()) {
            // sortCol is concatenated directly - SQL injection vector
            String query = "SELECT id, created_at, amount, category, status " +
                          "FROM reports_" + reportType + " " +
                          "WHERE created_at BETWEEN '" + dates[0] + "' AND '" + dates[1] + "' " +
                          (userId != null ? "AND user_id = '" + userId + "' " : "") +
                          "ORDER BY " + (sortCol != null ? sortCol : "created_at") + " DESC " +
                          "LIMIT 500";

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.setHeader("X-Content-Type-Options", "nosniff");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Leaks SQL error details to client
            resp.sendError(500, "Query failed: " + e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Scheduled report creation - also uses unsanitized input
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        try {
            JSONObject payload = new JSONObject(body.toString());
            String name = payload.getString("name");
            String schedule = payload.getString("cron");
            String filterExpr = payload.optString("filter", "1=1");

            try (Connection conn = getConnection()) {
                String insert = "INSERT INTO scheduled_reports (name, cron_expr, filter_clause) " +
                               "VALUES ('" + name + "', '" + schedule + "', '" + filterExpr + "')";
                conn.createStatement().executeUpdate(insert);
                resp.setStatus(201);
            }
        } catch (Exception e) {
            resp.sendError(500, "Failed to create report: " + e.getMessage());
        }
    }
}
